fs.writeFileSync('dist/app.js',"'use strict';\nlet data;\nconst getData=()=>data||(data=fetch('/data.json').then(r=>r.json()));\nconst status=document.querySelector('#audio-status');\nlet currentAudio,playToken=0;\nfunction stop(){playToken++;currentAudio?.pause();if('speechSynthesis'in window)window.speechSynthesis.cancel();}\ndocument.querySelector('#stop-sound')?.addEventListener('click',()=>{stop();status.textContent='Sound stopped.'});\ndocument.querySelector('#sound-mode')?.addEventListener('change',()=>{stop();status.textContent='Select a letter to try this sound mode.'});\ndocument.querySelectorAll('[data-letter]').forEach(btn=>btn.addEventListener('click',async()=>{\n stop();const token=playToken;document.querySelectorAll('.letter.selected').forEach(b=>b.classList.remove('selected'));btn.classList.add('selected');\n const mode=document.querySelector('#sound-mode').value,letter=btn.dataset.letter,word=btn.dataset.word;\n if(mode==='off'){status.textContent=`${letter} ${word}. Sound is off.`;return;}\n if(mode==='recorded'){\n  try{const manifest=await fetch('/audio-manifest.json').then(r=>r.json());if(token!==playToken)return;const src=manifest[letter];if(!src||!src.startsWith('/audio/')){status.textContent=`Reviewed recording for ${letter} has not been added yet.`;return;}\n   currentAudio=new Audio(src);await currentAudio.play();status.textContent=`Playing a reviewed recording for ${letter}.`;\n  }catch{status.textContent='This recording could not be played. Try again or ask an adult to say the sound.';}return;\n }\n if(!('speechSynthesis'in window)){status.textContent='This browser does not offer speech. Please say the letter together.';return;}\n const voice=window.speechSynthesis.getVoices().find(v=>v.localService&&/^hi(?:[-_]|$)/i.test(v.lang));\n if(!voice){status.textContent='No local Hindi voice is available. No cloud voice will be used. Ask an adult to say the sound.';return;}\n const phrase=word?`${letter}\u0964 ${word}`:letter;const utterance=new SpeechSynthesisUtterance(phrase);utterance.lang='hi-IN';utterance.voice=voice;utterance.rate=.75;\n utterance.onerror=()=>{status.textContent='Device speech could not play. Ask an adult to say the sound.'};window.speechSynthesis.speak(utterance);status.textContent=`Device voice: ${letter} ${word}. Synthetic speech, not a recorded lesson.`;\n}));\nwindow.addEventListener('pagehide',stop);\nconst signs=[['','inherent \u0905'],['\u093e','\u0906'],['\u093f','\u0907'],['\u0940','\u0908'],['\u0941','\u0909'],['\u0942','\u090a'],['\u0947','\u090f'],['\u0948','\u0910'],['\u094b','\u0913'],['\u094c','\u0914'],['\u0902','anusvar'],['\u0903','visarg']];\ndocument.querySelector('#consonant')?.addEventListener('change',e=>{document.querySelectorAll('#bar-grid .syllable > span').forEach((el,i)=>{el.textContent=e.target.value+signs[i][0]})});\ndocument.querySelector('#worksheet-letter')?.addEventListener('change',async e=>{const l=e.target.value,D=await getData();const item=[...D.swar,...D.vyanjan,...D.extra].find(x=>x[0]===l);document.querySelector('.practice-letter').replaceChildren(document.createTextNode(l+' '));const word=document.createElement('span');word.className='small hi';word.textContent=item?.[1]||'';document.querySelector('.practice-letter').append(word);document.querySelectorAll('.trace-row:not(.blank) span').forEach(el=>el.textContent=l)});\ndocument.querySelector('#print-sheet')?.addEventListener('click',()=>window.print());\n// App-inspired activities. Progress is tab-only by default, optional local storage via parent gate.\nconst KEY='hindi-web-practice-v1';let practice={stars:{},seconds:0},saveEnabled=false;try{const session=sessionStorage.getItem(KEY);if(session)practice=JSON.parse(session)}catch{}\ntry{const saved=localStorage.getItem(KEY);if(saved){practice=JSON.parse(saved);if(!practice.stars||typeof practice.stars!=='object')practice={stars:{},seconds:0};saveEnabled=true}}catch{}\nconst persistPractice=()=>{try{sessionStorage.setItem(KEY,JSON.stringify(practice))}catch{}if(saveEnabled)try{localStorage.setItem(KEY,JSON.stringify(practice))}catch{document.querySelector('#save-status')?.replaceChildren('Saving is unavailable in this browser. Progress stays in this tab.')}};\nconst refreshPractice=()=>{document.querySelectorAll('[data-star]').forEach(el=>{const earned=!!practice.stars[el.dataset.star];el.classList.toggle('earned',earned);el.classList.toggle('locked',!earned);el.querySelector('.star-label').textContent=earned?'\u2605 Practice star':'\u25cb Ready to try'});const total=Object.keys(practice.stars).length;document.querySelector('#gallery-status')?.replaceChildren(`${total} practice stars. Keep trying at your own pace.`);document.querySelector('#parent-stars')?.replaceChildren(String(total));document.querySelector('#parent-time')?.replaceChildren(`${Math.floor(practice.seconds/60)}m`)};\nrefreshPractice();setInterval(()=>{if(document.visibilityState==='visible'&&['/tracing/','/letters/','/barakhadi/','/numbers/','/stories/'].includes(location.pathname)){practice.seconds+=5;persistPractice();refreshPractice()}},5000);\nconst speechText=text=>{stop();const mode=document.querySelector('#sound-mode')?.value;if(mode!=='device'){status.textContent='Sound is off. Choose device mode if you want local Hindi speech.';return}const voice=window.speechSynthesis?.getVoices().find(v=>v.localService&&/^hi(?:[-_]|$)/i.test(v.lang));if(!voice){status.textContent='No local Hindi voice is available. Please read together. No cloud voice is used.';return}const u=new SpeechSynthesisUtterance(text);u.lang='hi-IN';u.voice=voice;u.rate=.75;u.onerror=()=>{status.textContent='Device speech could not play.'};speechSynthesis.speak(u);status.textContent='Playing synthetic local device speech.'};\ndocument.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>speechText(b.closest('details').querySelector('p').textContent)));\nconst gateForm=document.querySelector('#gate-form');if(gateForm){let tries=0;gateForm.addEventListener('submit',e=>{e.preventDefault();if(Number(document.querySelector('#gate-answer').value)===15){document.querySelector('#parent-gate').hidden=true;document.querySelector('#parent-panel').hidden=false;refreshPractice()}else{tries++;document.querySelector('#gate-status').textContent='Try again with a grown-up.';if(tries>=3){gateForm.querySelector('button').disabled=true;document.querySelector('#gate-status').textContent='Take a short break, then try again.';setTimeout(()=>{tries=0;gateForm.querySelector('button').disabled=false},15000)}}});const save=document.querySelector('#save-progress');save.checked=saveEnabled;const note=document.querySelector('#save-status');note.textContent=saveEnabled?'Saving on this browser is on.':'Progress is tab-only. Nothing is sent to us.';save.addEventListener('change',()=>{saveEnabled=save.checked;if(saveEnabled)persistPractice();else try{localStorage.removeItem(KEY)}catch{}note.textContent=saveEnabled?'Saving on this browser is on.':'Saved record removed. Progress is tab-only.'});document.querySelector('#reset-progress').addEventListener('click',()=>{if(!confirm('Clear practice stars and time on this browser?'))return;practice={stars:{},seconds:0};try{localStorage.removeItem(KEY);sessionStorage.removeItem(KEY)}catch{}refreshPractice();note.textContent='Practice stars and time cleared.'})}\nconst board=document.querySelector('#trace-board');if(board){const ctx=board.getContext('2d'),mask=document.createElement('canvas');mask.width=mask.height=360;const m=mask.getContext('2d',{willReadFrequently:true});let shape=[],covered=new Set(),down=false,points=0,onShape=0,previous=null,won=false;const picker=document.querySelector('#trace-letter');\nconst draw=async()=>{await document.fonts.ready;stop();shape=[];covered.clear();points=onShape=0;previous=null;won=false;m.clearRect(0,0,360,360);m.fillStyle='#000';m.textAlign='center';m.textBaseline='middle';m.font='230px Hindi';m.fillText(picker.value,180,190);const bytes=m.getImageData(0,0,360,360).data;for(let y=0;y<360;y+=5)for(let x=0;x<360;x+=5)if(bytes[(y*360+x)*4+3]>100)shape.push([x,y]);ctx.clearRect(0,0,360,360);ctx.fillStyle='#FFF8E1';ctx.fillRect(0,0,360,360);ctx.globalAlpha=.2;ctx.drawImage(mask,0,0);ctx.globalAlpha=1;document.querySelector('#trace-progress').value=0;document.querySelector('#trace-status').textContent='Trace the pale shape. Take your time.'};\nconst dab=(x,y)=>{points++;let near=false;shape.forEach(([sx,sy],i)=>{if(Math.hypot(sx-x,sy-y)<13){covered.add(i);near=true}});if(near)onShape++;ctx.fillStyle='#E65100';ctx.beginPath();ctx.arc(x,y,10,0,Math.PI*2);ctx.fill();const percent=shape.length?Math.round(100*covered.size/shape.length):0;document.querySelector('#trace-progress').value=percent;if(!won&&percent>=85&&points>=20&&onShape/points>=.35){won=true;practice.stars[picker.value]=true;persistPractice();document.querySelector('#trace-status').textContent='\u2605 Shabash! A practice star for your shape. Try another when you are ready.';refreshPractice()}};\nconst point=e=>{const r=board.getBoundingClientRect();return [(e.clientX-r.left)*360/r.width,(e.clientY-r.top)*360/r.height]};board.addEventListener('pointerdown',e=>{e.preventDefault();down=true;board.setPointerCapture(e.pointerId);previous=point(e);dab(...previous)});board.addEventListener('pointermove',e=>{if(!down)return;e.preventDefault();const p=point(e),dist=Math.hypot(p[0]-previous[0],p[1]-previous[1]);for(let i=1;i<=Math.ceil(dist/4);i++){let t=i/Math.ceil(dist/4);dab(previous[0]+(p[0]-previous[0])*t,previous[1]+(p[1]-previous[1])*t)}previous=p});for(const ev of ['pointerup','pointercancel','lostpointercapture'])board.addEventListener(ev,()=>{down=false;previous=null});picker.addEventListener('change',draw);document.querySelector('#trace-clear').addEventListener('click',draw);draw();}\n");
