const head=(title,desc,route)=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Hindi Varnmala</title><meta name="description" content="${esc(desc)}"><meta name="theme-color" content="#E65100">${base?`<link rel="canonical" href="${base}${route}"><meta property="og:url" content="${base}${route}">`:'<meta name="robots" content="noindex,follow">'}<meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:type" content="website"><link rel="icon" href="/app-icon.png" type="image/png"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header><div class="wrap"><a class="brand" href="/"><img class="logo" src="/app-icon.png" alt="Hindi Varnmala app logo" width="48" height="48"><span>Hindi Varnmala<small>By Team Handyapps</small></span></a><nav aria-label="Main navigation"><a href="/letters/">अ Seekho</a><a href="/tracing/">✏ Tracing</a><a href="/barakhadi/">का Bara</a><a href="/numbers/">१२ Ginti</a><a href="/stories/">☷ Kahani</a><a href="/gallery/">★ Gallery</a><a href="/parents/">Parents</a></nav></div></header><main id="main" class="wrap">`;
const foot=`</main><footer class="footer"><div class="wrap"><span>Little steps. A little Hindi, every day.<br>© ${new Date().getUTCFullYear()} Team Handyapps</span><div><a href="/numbers/">Numbers</a><a href="/parents/">For parents</a><a href="/privacy/">Privacy</a><a href="/support/">Support</a></div></div></footer></body></html>`;
const routes=[];
function page(route,title,desc,content){const dir=route==='/'?'dist':'dist'+route;fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(dir+'/index.html',head(title,desc,route)+content+foot);if(!routes.includes(route))routes.push(route);}
const appband=`<div class="appband"><div><h2>Keep learning in the app</h2><p>Hindi letters, audio, guided tracing, barakhadi and numbers.<br>The Play listing describes offline learning for ages 3-8.</p></div><a class="button" href="${play}" rel="noopener">View on Google Play ↗</a></div>`;
page('/','Hindi letters, little by little','Learn Hindi swar and vyanjan with letter charts, printable practice sheets, barakhadi and numbers. Resources for parents and early learners.',`<section class="hero"><div><div class="eyebrow">A playful beginning · Ages 3-8</div><h1>Big little steps<br>in Hindi.<span class="hi" lang="hi">अ से शुरू करें।</span></h1><p class="lead">One letter. One sound. One small discovery. Explore Hindi together, with simple activities for curious little learners.</p><div class="actions"><a class="button" href="/letters/">Explore the letters →</a><a class="button secondary" href="${play}" rel="noopener">Get the Android app ↗</a></div><p class="small">Made for learning together. No sign-up to use these resources.</p></div><div class="art" aria-label="Illustrative Hindi letter cards"><span class="pill">TODAY'S LITTLE DISCOVERY</span><div class="letters"><span lang="hi">अ</span><span lang="hi">आ</span><span lang="hi">क</span></div><div class="caption"><span lang="hi" class="hi">अ से अनार · आ से आम</span><span>LOOK · SAY · TRY</span></div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">A few minutes is a good start</div><h2>Choose a little adventure</h2></div><p class="small">Explore at your child's pace.</p></div><div class="cards"><a class="card" href="/letters/"><span class="icon" lang="hi">अ आ</span><h3>Meet the letters →</h3><p>Swar and vyanjan cards, Hindi words and an optional sound mode.</p></a><a class="card" href="/worksheets/"><span class="icon" lang="hi">क ख</span><h3>Print & practice →</h3><p>Choose a letter. Print a calm, uncluttered sheet. Trace, then try on your own.</p></a><a class="card" href="/barakhadi/"><span class="icon" lang="hi">का कि</span><h3>Make new sounds →</h3><p>Explore how matras change a consonant in our barakhadi practice chart.</p></a></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Count something real</div><h2>One mango. Two little hands.</h2></div><a href="/numbers/">Explore numbers 1-20 →</a></div><p class="lead">Count toys, steps or spoons. Pair Hindi words with the things your child already knows.</p><div class="chiprow"><span class="hi" lang="hi">१ · एक</span><span class="hi" lang="hi">२ · दो</span><span class="hi" lang="hi">३ · तीन</span><span class="hi" lang="hi">४ · चार</span></div></section><section class="section">${appband}<p class="small">App features are based on its developer-provided Play listing. Website sound availability depends on your device. No fabricated ratings or learning guarantees.</p></section>`);
const lettercards=items=>items.map(([l,w,e])=>`<button class="letter" data-letter="${l}" data-word="${w}" aria-label="${esc(l+' '+w)}"><span class="glyph" lang="hi">${l}</span><span class="picture" aria-hidden="true">${SOURCE.ART[l]||SOURCE.EMOJI[l]||"✦"}</span><span class="word" lang="hi">${w||'·'}</span><span class="english">${e}</span></button>`).join('');
page('/letters/','Hindi swar and vyanjan chart','Explore Hindi vowels, consonants and additional signs with examples. Optional Hindi speech uses a local device voice when available.',`<div class="pagehead"><div class="eyebrow">Look · Listen · Repeat</div><h1>Meet the Hindi letters</h1><p class="lead">Choose a card and say it together. Start with a few familiar letters, not the whole chart.</p></div><div class="soundcontrols"><label>Sound <select id="sound-mode"><option value="off">Off (default)</option><option value="recorded">Recordings (not yet added)</option><option value="device">Device Hindi voice (local only)</option></select></label><button class="button secondary" id="stop-sound">Stop sound</button></div><p id="audio-status" class="status" role="status" aria-live="polite">Sound is off. Select a mode to hear a letter where available.</p><div class="note">Device speech is synthetic and may pronounce individual letters unevenly. Only local Hindi voices are used; no cloud speech fallback. Recordings (not yet added) will be available when added. Ask an adult or teacher to model sounds.</div><div class="tabs"><a href="#swar">Swar</a><a href="#vyanjan">Vyanjan</a></div><section id="swar"><h2>Swar <span class="hi" lang="hi">स्वर</span></h2><p>Independent vowel forms. Use the example words as a starting point.</p><div class="lettergrid">${lettercards(D.swar)}</div></section><section id="vyanjan"><h2>Vyanjan <span class="hi" lang="hi">व्यंजन</span></h2><p>Consonants are grouped in a familiar teaching order. Some letters are easier to notice inside words.</p><div class="lettergrid">${lettercards(D.vyanjan)}</div></section><p class="small wide">Grouping follows the app: signs and conjunct forms are included in its teaching sequence. This is not a universal letter count. Follow your teacher.</p>`);
const cons=D.vyanjan.filter(x=>!['ङ','ञ','ण'].includes(x[0]));
const matras=[['','inherent अ'],['ा','आ'],['ि','इ'],['ी','ई'],['ु','उ'],['ू','ऊ'],['े','ए'],['ै','ऐ'],['ो','ओ'],['ौ','औ'],['ं','anusvar'],['ः','visarg']];
page('/barakhadi/','Hindi barakhadi practice','Explore a consonant with common matras. A simple interactive Hindi barakhadi chart for parent-led practice.',`<div class="pagehead"><div class="eyebrow">Build sounds together</div><h1>One letter, new sounds</h1><p class="lead">A consonant changes when we add a vowel sign (matra). Try the row slowly with an adult.</p></div><div class="worksheet-control"><label for="consonant">Choose a consonant</label><select id="consonant">${cons.map(([c])=>`<option value="${c}">${c}</option>`).join('')}</select></div><div class="bargrid" id="bar-grid">${matras.map(([m,label])=>`<div class="syllable"><span lang="hi">क${m}</span><small>${label}</small></div>`).join('')}</div><div class="prose"><h2>Look closely at <span class="hi" lang="hi">कि</span></h2><p>The short इ sign appears before the consonant on the page, but the syllable is read with the consonant first. Compare <span class="hi" lang="hi">कि</span> and <span class="hi" lang="hi">की</span> with your teacher.</p><div class="note">This beginner row includes anusvar and visarg practice at the end. These are not vowel matras in the same sense as ा or ि. ऋ forms and more complex combinations are outside this starter chart.</div><h2>A two-minute activity</h2><p>Choose क. Say क, का, कि, की together. Then find a familiar word such as <span class="hi" lang="hi">किताब</span>. Stop when your child needs a break.</p></div>`);
page('/numbers/','Hindi numbers 1 to 20','Hindi ginti 1 to 20 with Devanagari numerals and Hindi names. Simple counting ideas for early learners.',`<div class="pagehead"><div class="eyebrow">Count · Point · Say</div><h1>A little Hindi counting</h1><p class="lead">Start with one to five. Count real things before moving to the next numbers.</p></div><div class="numbergrid">${D.numbers.map(([n,w],i)=>`<div class="number"><strong lang="hi">${n}</strong><span class="word" lang="hi">${w}</span><p class="small">${i+1}</p></div>`).join('')}</div><div class="prose"><h2>Make it a small game</h2><p>Put three spoons on the table. Touch each one as you say <span class="hi" lang="hi">एक, दो, तीन</span>. Ask your child to give you two spoons. Try with toys tomorrow.</p><p>Hindi number spellings can have regional variants. Use the form taught at your child's school.</p></div>`);
const letters=[...D.swar,...D.vyanjan,...D.extra];
const sheet=(l,w)=>`<h2>My little Hindi practice</h2><div class="topline"><span>Name: __________________</span><span>Date: _________________</span></div><p class="instruction">Say the letter together. Trace the pale shapes, then try your own. This is shape practice, not a stroke-order guide.</p><p class="practice-letter" lang="hi">${l} <span class="small hi">${w}</span></p>${[1,2,3].map(()=>`<div class="trace-row" lang="hi"><span>${l}</span><span>${l}</span><span>${l}</span><span>${l}</span><span>${l}</span></div>`).join('')}<div class="trace-row blank"></div><p class="instruction">Draw something that reminds you of this letter.<br><br>Made by Team Handyapps · Hindi Varnmala · For parent-led practice</p>`;
page('/worksheets/','Printable Hindi letter practice sheets','Choose a Hindi letter and print an original A4 tracing and free-writing practice sheet. No sign-up or download service needed.',`<div class="pagehead"><div class="eyebrow">Pencil time</div><h1>Print a little practice</h1><p class="lead">One letter at a time. Choose, print, and let your child try without rushing.</p></div><div class="worksheet-control"><label for="worksheet-letter">Letter</label><select id="worksheet-letter">${letters.map(([l,w])=>`<option value="${l}">${l} ${w}</option>`).join('')}</select><button class="button" id="print-sheet">Print / save as PDF</button></div><p class="small no-print">Use A4 portrait. In the print dialog, turn off browser headers and footers. The pale letters are tracing shapes, not numbered stroke instructions.</p><div class="paper" id="sheet">${sheet('अ','अनार')}</div>`);
page('/parents/','Simple Hindi learning activities for parents','Short parent-led Hindi letter, counting and writing activities. Gentle practice ideas without tests or progress tracking.',`<div class="pagehead"><div class="eyebrow">For grown-ups</div><h1>Keep it small. Keep it kind.</h1><p class="lead">You don't need to finish a chart in one sitting. A familiar word and a few minutes together are a useful beginning.</p></div><article class="prose"><h2>Start with something your child knows</h2><p>Point to an आम or a picture of one. Say the word together, then show आ. A letter is easier to remember when it has a familiar word beside it.</p><h2>Look, say, try</h2><ol><li>Choose two or three cards on the <a href="/letters/">letter chart</a>.</li><li>Model the sound yourself, or use a reviewed recording when available. Device speech is only an optional aid.</li><li>Invite your child to point to a letter or say a word. No score needed.</li><li>Try one <a href="/worksheets/">printable sheet</a>, if your child enjoys pencil time.</li></ol><h2>When letters look alike</h2><p>Place two cards beside each other. Notice a line, curve or mark rather than turning it into a test. Your child's teacher can help with sound distinctions and stroke order.</p><h2>Follow the school sequence</h2><p>Hindi charts differ in their grouping of vowels, signs and conjuncts. Use these resources alongside your school's material, not in place of it. Stop or change activities when your child loses interest.</p><h2>A note on this first edition</h2><p>These are original beginner practice layouts. They do not promise a reading outcome or a fixed learning timeline. Pronunciation recordings and formal Hindi educator review are still to be added.</p></article>`);
page('/privacy/','Privacy and website information','What this Hindi Varnmala website does and does not collect, plus the difference between website and app privacy information.',`<div class="pagehead"><div class="eyebrow">Clear, simple information</div><h1>Privacy</h1><p>Website policy · Updated October 8, 2026</p></div><article class="prose"><h2>This website</h2><p>The website contains learning resources from Team Handyapps. It has no user accounts, analytics scripts, advertising, trackers, cookies or child progress profiles in its application code. Letter choices and sound preferences are kept only in the current page session; they are not saved or sent to us.</p><h2>Hosting and basic requests</h2><p>Your browser requests pages, fonts, code and any enabled audio files from the site's hosting provider. Hosting infrastructure may process standard technical information such as IP addresses and request logs to serve and secure the website. This application does not add its own visitor logging. Hosting-provider retention and settings must be checked when the site is deployed.</p><h2>Optional audio</h2><p>Sound is off by default. Recordings (not yet added), when supplied, load from this website. The optional device speech mode uses only a Hindi voice reported by the browser as local. It does not fall back to a remote voice. Voice availability and pronunciation vary. No microphone access is requested.</p><h2>Printing</h2><p>Printing uses your browser's print dialog. No completed worksheets or child names are submitted to this site.</p><h2>Links to the app</h2><p>Google Play is a separate service. Its privacy practices apply when you follow the app link. The <a href="${play}">app listing</a> declares no data collected or shared, and describes no ads or in-app purchases. Those are developer-provided app declarations, not a statement about hosting logs for this website. The app's current privacy-policy link is available on its Play listing; this website policy does not silently replace it.</p><h2>Support email</h2><p>If you email <a href="mailto:teamhandyapps@gmail.com">teamhandyapps@gmail.com</a>, your email provider and ours process the message. Include only what is needed for support. Adults should contact us; do not include children's personal information.</p><h2>Changes</h2><p>If we add services or data collection in future, this policy must be updated before those changes go live.</p></article>`);
page('/support/','Hindi Varnmala support','Contact Team Handyapps for Hindi Varnmala support. Guidance for parents on audio, printing and reporting errors.',`<div class="pagehead"><div class="eyebrow">For parents and carers</div><h1>A little help</h1><p class="lead">Questions or something that needs fixing? An adult can contact Team Handyapps.</p></div><article class="prose"><a class="button" href="mailto:teamhandyapps@gmail.com">Email Team Handyapps</a><p class="small">teamhandyapps@gmail.com · No response-time promise.</p><h2>I can't hear the letters</h2><p>Sound is off by default. Select a sound mode on the letters page. Recordings (not yet added) are not included in this first edition. Device mode requires a local Hindi voice; if none is present, the site will say so and will not send text to a cloud voice. Use your own pronunciation or the Android app instead.</p><h2>How do I save a worksheet?</h2><p>Choose a letter, then select Print / save as PDF. Your browser may offer a PDF destination. Use A4 portrait and disable browser headers and footers.</p><h2>Tell us about a content issue</h2><p>Include the page and the letter or word involved. A cropped screenshot can help, but do not send a child's name, photo, voice or school details. Teachers' corrections are welcome.</p><h2>Android app</h2><p><a href="${play}">Open the Hindi Varnmala Play listing</a> for the current app details and its app-specific support and policy links.</p></article>`);

const picker=[...D.swar,...D.vyanjan,...Array.from({length:10},(_,i)=>[String(i),i===0?'शून्य':SOURCE.CONTENT.ginti[i-1][1],''])];
const options=picker.map(([c,w])=>`<option value="${c}">${c} ${w}</option>`).join('');
page('/tracing/','Tracing Hindi letters and digits','Trace Hindi letters and digits on screen. Shape coverage practice, not a stroke-order lesson.',`<div class="pagehead"><div class="eyebrow">✎ Tracing · लिखो</div><h1>Trace. Try. Celebrate.</h1><p class="lead">Follow the pale shape with a finger or mouse. Letters and digits match the app's picker.</p></div><section class="practice-card"><div class="worksheet-control"><label for="trace-letter">Choose a letter or digit</label><select id="trace-letter">${options}</select><button id="trace-clear" class="button secondary">Try again</button></div><canvas id="trace-board" width="360" height="360" aria-label="Finger tracing board"></canvas><label class="trace-progress">Shape covered <progress id="trace-progress" max="100" value="0"></progress></label><p id="trace-status" role="status" aria-live="polite">Trace the pale shape to earn a practice star.</p><p class="small">This checks shape coverage, not handwriting quality or stroke order. It is not a learning assessment. <a href="/worksheets/">Prefer paper? Print a sheet →</a></p></section>`);
page('/stories/','Kahani and rhymes','Hindi stories and rhymes from the app, for grown-ups and children to read together.',`<div class="pagehead"><div class="eyebrow">☷ Kahani · कहानियाँ</div><h1>A little story time</h1><p class="lead">The app's six stories and five rhymes, ready to read together. Optional speech needs a local Hindi device voice.</p></div><div class="soundcontrols"><label>Sound <select id="sound-mode"><option value="off">Off (default)</option><option value="device">Device Hindi voice (local only)</option></select></label><button id="stop-sound" class="button secondary">Stop sound</button></div><p id="audio-status" role="status" class="status">Sound is off.</p><section class="story-list">${[...SOURCE.CONTENT.stories,...SOURCE.CONTENT.rhymes].map((s,i)=>`<details class="story"><summary><span aria-hidden="true">${SOURCE.STORY_EMOJI[s.t]||'☷'}</span> <span lang="hi">${esc(s.t)}</span><small>${i<6?'Story':'Rhyme'}</small></summary><p lang="hi">${esc(s.b)}</p><button class="button secondary" data-story="${i}">Bolo · Listen</button></details>`).join('')}</section><p class="small">Traditional texts retold in the app. Read with an adult. Device speech is synthetic, not a recorded storyteller.</p>`);
page('/gallery/','Practice star gallery','Celebrate tracing attempts with a private practice-star gallery on this device.',`<div class="pagehead"><div class="eyebrow">★ Gallery · शाबाश!</div><h1>Little stars, big smiles.</h1><p class="lead">Practice a shape on the tracing board to unlock its tile. Stars celebrate trying, not a test result.</p></div><p id="gallery-status" role="status"></p><div class="lettergrid" id="star-gallery">${picker.map(([c,w])=>`<div class="letter locked" data-star="${c}"><span class="glyph" lang="hi">${c}</span><span class="word" lang="hi">${w}</span><span class="star-label">○ Ready to try</span></div>`).join('')}</div><p class="note">Progress stays in this tab unless a parent chooses to save it on this browser. It is not sent to Team Handyapps and does not sync with the Android app.</p>`);
page('/parents/','Parents and private practice progress','A parent gate, optional on-device practice progress and gentle Hindi learning tips.',`<div class="pagehead"><div class="eyebrow">👪 Parents · साथ सीखें</div><h1>A little help from you.</h1><p class="lead">Sit together, say a familiar word, then try one small activity.</p></div><section class="practice-card" id="parent-gate"><h2>For grown-ups</h2><p id="gate-question">What is 8 + 7?</p><form id="gate-form"><label for="gate-answer">Answer</label> <input id="gate-answer" type="number" inputmode="numeric" autocomplete="off" required><button class="button">Open</button></form><p id="gate-status" role="status"></p><p class="small">A small accidental-tap guard, not proof of age or a security lock.</p></section><section id="parent-panel" hidden class="practice-card"><h2>Practice on this browser</h2><div class="kpis"><div><strong id="parent-stars">0</strong><span>practice stars</span></div><div><strong id="parent-time">0m</strong><span>active practice</span></div></div><label><input type="checkbox" id="save-progress"> Save practice stars and time on this browser</label><p id="save-status" role="status" class="small"></p><button class="button secondary" id="reset-progress">Reset progress</button><p class="small">No account, name, microphone or cloud profile. Browser storage is optional and can be cleared here. It does not connect to the app's progress.</p></section><article class="prose"><h2>Look, say, try</h2><p>Choose two or three cards in <a href="/letters/">Seekho</a>. Say the word together. Try <a href="/tracing/">Tracing</a>, or print a <a href="/worksheets/">practice sheet</a>. Stop when your child needs a break.</p><h2>Follow your teacher's sequence</h2><p>Vowels, signs and conjunct forms are grouped as in the app. Curricula differ. These practice activities do not replace teaching or promise a reading outcome.</p><h2>App and website</h2><p>The Android app includes bundled synthetic letter audio and offline use. This website needs a connection to load and has no installed offline mode. We have not copied the app's audio until voice-model redistribution terms are verified. Browser Hindi speech is an optional local-only aid.</p><p><a href="/privacy/">Website privacy</a> · <a href="/support/">Support</a> · <a href="${play}">Android app on Google Play</a></p></article>`);
page('/','Hindi Varnmala - learn, trace and play','Explore the Hindi Varnmala app activities on the web: letters, tracing, barakhadi, counting, stories and practice stars.',`<section class="hero"><div><div class="eyebrow">Seekho · Likho · Bolo</div><h1>A little Hindi.<br>A lot of discovery.<span class="hi" lang="hi">आओ, साथ सीखें!</span></h1><p class="lead">The familiar Hindi Varnmala world, now on the web. Meet a letter, trace its shape, and find a little story to read together.</p><div class="actions"><a class="button" href="/letters/">अ Start learning →</a><a class="button secondary" href="${play}">Get the Android app ↗</a></div><p class="small">For parent-led practice · No ads or sign-up</p></div><div class="app-art"><img src="/app-icon.png" alt="Hindi Varnmala app icon with Hindi letters, stars and pencil" width="240" height="240"><span class="pill">Same little learning world</span></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Pick your next small step</div><h2>Choose an adventure</h2></div></div><div class="cards">${[['अ','Seekho','letters','Swar, vyanjan and familiar word pictures.'],['✎','Tracing','tracing','Trace a letter or digit with your finger.'],['का','Barakhadi','barakhadi','Explore a consonant with new sounds.'],['१२','Ginti','numbers','Count in Hindi from one to twenty.'],['☷','Kahani','stories','Six stories and five rhymes to read together.'],['★','Gallery','gallery','Celebrate shape practice with private stars.']].map(([icon,t,r,d])=>`<a class="card" href="/${r}/"><span class="icon">${icon}</span><h3>${t} →</h3><p>${d}</p></a>`).join('')}</div></section><section class="section"><div class="appband"><div><h2>Made for little learners.<br>Shared with grown-ups.</h2><p>Want paper time? Print a letter sheet.<br>Want offline learning and bundled audio? Use the Android app.</p></div><div class="actions"><a class="button" href="/worksheets/">Print & practice →</a><a class="button" href="/parents/">Parents →</a></div></div></section>`);
